package com.example.jalalidaily;
import android.content.*;import org.json.*;import java.net.*;import java.io.*;import java.nio.charset.StandardCharsets;
public final class Holidays{
 static String key(int y,int m,int d){return String.format(java.util.Locale.US,"%04d-%02d-%02d",y,m,d);}
 static boolean holiday(Context c,int y,int m,int d){return c.getSharedPreferences("holidays",0).getBoolean(key(y,m,d)+":holiday",false);}
 static String events(Context c,int y,int m,int d){return c.getSharedPreferences("holidays",0).getString(key(y,m,d)+":events","");}
 static void loadMonth(Context c,int y,int m,Runnable done){new Thread(()->{android.content.SharedPreferences p=c.getSharedPreferences("holidays",0);for(int d=1;d<=Jalali.daysInMonth(y,m);d++){String k=key(y,m,d);if(p.contains(k+":holiday")&&System.currentTimeMillis()-p.getLong(k+":updated",0L)<7L*24*60*60*1000)continue;try{URL url=new URL("https://holidayapi.ir/jalali/"+y+"/"+m+"/"+d);HttpURLConnection conn=(HttpURLConnection)url.openConnection();conn.setConnectTimeout(5000);conn.setReadTimeout(5000);if(conn.getResponseCode()!=200){conn.disconnect();continue;}ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(InputStream in=conn.getInputStream()){byte[] buf=new byte[4096];int n;while((n=in.read(buf))!=-1)bytes.write(buf,0,n);}conn.disconnect();JSONObject o=new JSONObject(bytes.toString("UTF-8"));StringBuilder names=new StringBuilder();JSONArray events=o.optJSONArray("events");if(events!=null)for(int i=0;i<events.length();i++){JSONObject ev=events.optJSONObject(i);if(ev!=null){if(names.length()>0)names.append("، ");names.append(ev.optString("description"));}}p.edit().putBoolean(k+":holiday",o.optBoolean("is_holiday")).putString(k+":events",names.toString()).putLong(k+":updated",System.currentTimeMillis()).apply();}catch(Exception ignored){}}new android.os.Handler(android.os.Looper.getMainLooper()).post(done);}).start();}
}